function fillStyle(percent) {
  const p = Math.max(0, Math.min(100, Math.round(percent / 5) * 5))
  const dawn = Math.max(0, Math.min(1, (p - 60) / 35))
  const drop = Math.round(150 * Math.min(p / 95, 1))
  return `.dawn{transform:scaleY(${(0.15 + 0.85 * dawn).toFixed(2)});opacity:${dawn === 0 ? 0 : (0.4 + 0.6 * dawn).toFixed(2)}}` +
    `.paleSky{opacity:${(0.3 * p / 100).toFixed(2)}}` +
    `.moonSet{transform:translateY(${drop}px);opacity:${(1 - 0.55 * dawn).toFixed(2)}}`
}
// The backdrop for a context that is `percent` full.
export const scene = percent => SCENE_A + fillStyle(percent) + SCENE_B
